def icon(*parts):
    return '<svg class="pin" viewBox="0 0 24 24" aria-hidden="true">' + ''.join(f'<path d="{d}" style="fill:{c}"/>' for d, c in parts) + '</svg>'

GRAY, SKY, ROSE = 'var(--color-fg-tertiary)', 'var(--color-fg-accent)', 'var(--rose-400)'
P = {
    'p0': ('지금 · 선 아이콘', icon((D_LINE, GRAY)), 'Line/Navigation/map-pin. 선이 가늘고 속이 비어 옆 글자보다 약해 보여요'),
    'p1': ('채움 · 회색', icon((D_FILL, GRAY)), 'Fill/Navigation/map-pin. 같은 모양을 채워서 글자 무게와 맞춤'),
    'p2': ('채움 · 하늘', icon((D_FILL, SKY)), 'Fill/Navigation/map-pin을 야화 하늘색으로. 아래 아이콘들(하늘)과 색이 이어짐'),
    'p3': ('하트 핀 · 회색', icon((D_HEART, GRAY)), 'Fill/Navigation/map-pin-heart. 핀 안에 작은 하트가 뚫려 있어 데이팅 앱다움'),
    'p4': ('하트 핀 · 로즈', icon((D_HEART, ROSE)), '하트 핀을 옅은 로즈로. 가장 따뜻하지만 눈에 띄는 편'),
    'p5': ('두 색 · 하늘 점', icon((D_DUO_OUT, GRAY), (D_DUO_DOT, SKY)), 'Duocolor/Navigation/map-pin. 바깥은 회색 선, 가운데 점만 하늘색'),
    'p6': ('두 색 · 로즈 하트', icon((D_DUO_OUT, GRAY), (D_DUO_HEART, ROSE)), 'Duocolor/Navigation/map-pin-heart. 회색 핀 안에 로즈 하트'),
}
CSS = COMMON + '.r-tags{font-size:14px;gap:4px 12px}.pin{width:16px;height:16px;flex:none}.r-meta.big .pin{width:18px;height:18px}'

if __name__ == '__main__':
    for k, (name, ic, _) in P.items():
        body = f'<h2 class="r-name">{NAME}</h2><p class="r-meta">{ic}{REGION}<i></i>{GENDER}</p>' + tagline('') + KEY + LIFE + FILTER
        (HERE / f'{k}.html').write_text(page(f'위치 아이콘 {name}', body, CSS, HATCH_JS))
    print('built', ', '.join(P))
